2|import { createServer } from 'http';
3|import { Server } from 'socket.io';
4|import jwt from 'jsonwebtoken';
5|import { createClient } from 'redis';
6|import { assignChunk } from './chunks.js';
7|import { placeBuilding, activateBooster, requestLink, confirmLink } from './actions.js';
8|import { runTick } from './tick.js';
9|import { db } from './db.js';
10|
11|export function createApp() {
12|  const app = express();
13|  app.use(express.json({ limit: '256kb' }));
14|  app.get('/health', (_req, res) => res.json({ ok: true }));
15|  app.get('/', (_req, res) => res.json({ name: 'stranded-horizons-server', v: 1 }));
16|  // Admin chunk list for the Leaflet live map. Bearer [REDACTED], allowlist-checked.
17|  app.get('/admin/chunks', async (req, res) => {
18|    try {
19|      const token = String(req.headers.authorization || '').replace(/^Bearer\s+/i, '');
20|      const payload = verifyToken(token);
21|      const me = (await db.query(
22|        'select (select count(*) from admin_allowlist where user_id = $1) > 0 as is_admin',
23|        [payload.sub]
24|      )).rows[0]?.is_admin;
25|      if (!me) return res.status(403).json({ ok: false, error: 'forbidden' });
26|      const r = await db.query(
27|        'select id, chunk_x, chunk_y, world_x, world_y, efficiency_cached, owner_id, created_at from bases limit 10000'
28|      );
29|      res.json(r.rows);
30|    } catch {
31|      res.status(401).json({ ok: false, error: 'unauthorized' });
32|    }
33|  });
34|  return app;
35|}
