39|  // Hobby default: Supabase JWT secret (HS256). VPS/self-host sets SUPABASE_JWT_SECRET.
40|  // Vercel preview without auth configured: allow DEV_UNAUTHENTICATED=1 for CI smoke only.
41|  if (process.env.DEV_UNAUTHENTICATED === '1') return { sub: 'dev-user' };
42|  return jwt.verify(raw, process.env.SUPABASE_JWT_SECRET);
43|}
44|
45|export function attachSockets(http, opts = {}) {
46|  const origins = (process.env.CORS_ORIGINS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
47|  const io = new Server(http, { cors: { origin: origins.length ? origins : true } });
48|
49|  io.use((socket, next) => {
50|    try {
51|      const payload = verifyToken(socket.handshake.auth?.token);
52|      socket.data.userId = payload.sub;
53|      next();
54|    } catch {
55|      next(new Error('unauthorized'));
56|    }
57|  });
58|
