60|  let pub = null;
61|  if (process.env.REDIS_URL && !opts.skipRedis) {
62|    pub = createClient({ url: process.env.REDIS_URL });
63|    pub.connect().catch(() => { pub = null; });
64|  }
65|
66|  io.on('connection', (socket) => {
67|    const uid = () => socket.data.userId;
68|    socket.on('chunk:get', async (ack) => {
69|      try { ack({ ok: true, base: await assignChunk(uid()) }); }
70|      catch (e) { ack({ ok: false, error: e.message === 'world_full' ? 'world_full' : 'chunk_failed' }); }
71|    });
72|    socket.on('place', async (msg, ack) => {
73|      try { ack(await placeBuilding(uid(), msg)); }
74|      catch { ack({ ok: false, error: 'place_failed' }); }
75|    });
76|    socket.on('booster:activate', async (ack) => {
77|      try { ack(await activateBooster(uid())); }
78|      catch { ack({ ok: false, error: 'booster_failed' }); }
79|    });
80|    socket.on('link:request', async (msg, ack) => {
81|      try { ack(await requestLink(uid(), msg?.targetBaseId)); }
82|      catch { ack({ ok: false, error: 'link_failed' }); }
83|    });
84|    socket.on('link:confirm', async (msg, ack) => {
85|      try { ack(await confirmLink(uid(), msg?.otherBaseId, msg?.accept !== false)); }
86|      catch { ack({ ok: false, error: 'link_failed' }); }
87|    });
88|    // Admin console (server re-checks admin flag on every command).
89|    socket.on('admin:cmd', async (msg, ack) => {
90|      try {
91|        const me = (await db.query(
92|          `select (select count(*) from admin_allowlist where user_id = $1) > 0 as is_admin`, [uid()]
93|        )).rows[0]?.is_admin;
94|        if (!me) { ack({ ok: false, error: 'forbidden' }); return; }
95|        const [cmd, ...rest] = String(msg?.line || '').trim().split(/\s+/);
96|        await db.query('insert into admin_audit (admin_id, action, payload_json) values ($1,$2,$3)',
97|          [uid(), cmd || 'noop', JSON.stringify({ line: msg?.line || '' })]);
98|        if (pub) await pub.publish('chunk:update', JSON.stringify({ by: uid(), cmd: cmd || 'noop' }));
99|        ack({ ok: true, ran: cmd || 'noop', args: rest });
100|      } catch { ack({ ok: false, error: 'admin_failed' }); }
101|    });
102|  });
103|
104|  return io;
105|}
