111|  const http = createServer(app);
112|  attachSockets(http);
113|  let n = Math.floor(Date.now() / 2000);
114|  setInterval(() => { n += 1; runTick('shard-0', n).catch(() => {}); }, 2000);
115|  const port = Number(process.env.PORT || 3000);
116|  http.listen(port, () => console.log(`sh-server listening on :${port}`));
